from datetime import datetime, timedelta
from QuantConnect import Resolution, TimeZones
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data import Slice
from QuantConnect.Data.Consolidators import TradeBarConsolidator
from QuantConnect.Data.Market import TradeBar
from QuantConnect.Indicators import SimpleMovingAverage
from QuantConnect.Orders import OrderStatus
from QuantConnect.Securities import DataNormalizationMode
from QuantConnect.Securities.Option import OptionRight


class SpyFiveMinuteCallStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )
        self.option = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.last_bar_end = None
        self.current_slice = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        self.current_slice = slice

        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing()
        self.HandleTimeStop()

        if self.entry_symbol is not None and self.entry_price is not None:
            self.CheckProfitTarget(slice)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        if bar.Symbol != self.spy:
            return

        # Do not update indicators across missing five-minute intervals.
        if self.last_bar_end is not None:
            if bar.End - self.last_bar_end != timedelta(minutes=5):
                self.Debug(
                    "Missing SPY five-minute bar; skipping indicator update at "
                    + str(bar.End)
                )
                self.last_bar_end = bar.End
                return

        self.last_bar_end = bar.End

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.End, bar.Close)
        self.slow.Update(bar.End, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if previous_fast is None or previous_slow is None:
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        bar_time = bar.End.time()
        eligible_time = datetime.min.time().replace(
            hour=9, minute=45
        ) <= bar_time <= datetime.min.time().replace(
            hour=14, minute=30
        )

        if bullish_cross and eligible_time:
            self.TryEnterCall(bar.Close, bar.End.date())

    def TryEnterCall(self, spy_price, algorithm_date):
        if self.current_slice is None:
            return

        if self.entry_symbol is not None:
            return

        if self.entry_ticket is not None:
            if self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ):
                return

        if self.blocked_entry_date == algorithm_date:
            return

        chains = list(self.current_slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: current Slice has no option chain.")
            return

        contracts = []
        for chain in chains:
            for contract in chain.Contracts.Values:
                if contract.Right == OptionRight.Call:
                    contracts.append(contract)

        minimum_expiry = algorithm_date + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration satisfies the seven-day rule.")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no call satisfies the expiration and strike rules."
            )
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(self.entry_symbol, 1)

        self.Debug(
            "Call entry submitted: "
            + str(self.entry_symbol)
            + " at "
            + str(self.Time)
        )

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "Call entry filled: "
                        + str(self.entry_symbol)
                        + " at "
                        + str(self.entry_price)
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.entry_ticket = None
                    self.entry_symbol = None
                    self.entry_price = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    if order_event.Status == OrderStatus.Filled:
                        self.Debug(
                            "Call exit filled: "
                            + str(self.entry_symbol)
                            + " at "
                            + str(order_event.FillPrice)
                        )
                    self.exit_ticket = None

                    if (
                        self.entry_symbol is not None
                        and self.Portfolio[self.entry_symbol].Quantity == 0
                    ):
                        self.entry_ticket = None
                        self.entry_symbol = None
                        self.entry_price = None

    def CheckProfitTarget(self, slice: Slice):
        if self.exit_ticket is not None:
            return

        if self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if holding.Quantity <= 0:
            return

        quote = slice.BidAsks.get(self.entry_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.exit_ticket = self.Liquidate(self.entry_symbol)
            self.Debug(
                "Profit target reached for "
                + str(self.entry_symbol)
                + " at midpoint "
                + str(midpoint)
            )

    def HandleTimeStop(self):
        if self.entry_symbol is None or self.exit_ticket is not None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if holding.Quantity <= 0:
            return

        expiry = self.Securities[self.entry_symbol].Symbol.ID.Date.date()
        prior_trading_date = self._PreviousTradingDate(expiry)

        if (
            self.Time.date() == prior_trading_date
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self.exit_ticket = self.Liquidate(self.entry_symbol)
            self.Debug("Expiration-eve time stop submitted.")

    def HandleExpirationProcessing(self):
        if self.entry_symbol is None:
            return

        expiry = self.Securities[self.entry_symbol].Symbol.ID.Date.date()

        if self.Time.date() >= expiry:
            self.blocked_entry_date = self.Time.date()

            if self.Portfolio[self.entry_symbol].Quantity > 0:
                if self.exit_ticket is None:
                    self.exit_ticket = self.Liquidate(self.entry_symbol)
                    self.Debug(
                        "Unexpected expiration carry: liquidation submitted for "
                        + str(self.entry_symbol)
                    )

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug(
                "Unexpected exercise or assignment created SPY position; "
                "liquidating immediately."
            )
            self.Liquidate(self.spy)

    def _PreviousTradingDate(self, date_value):
        date_value -= timedelta(days=1)
        while date_value.weekday() >= 5:
            date_value -= timedelta(days=1)
        return date_value
