    def OnData(self, slice: Slice):
        self.latest_slice = slice

        self._handle_unexpected_spy_position()
        self._manage_existing_option_position(slice)

        if self._entry_order_is_open() or self._option_position_exists():
            return

        if self.expiration_blocked_date == self.Time.date():
            return

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar)

    def _process_minute_bar(self, bar: TradeBar):
        local_start = bar.EndTime.astimezone(self.TimeZone).replace(tzinfo=None)

        if local_start.time() < time(9, 30) or local_start.time() >= time(16, 0):
            return

        minutes_from_open = (
            local_start.hour * 60 + local_start.minute
        ) - (9 * 60 + 30)

        if minutes_from_open < 0:
            return

        bucket_number = minutes_from_open // 5
        bucket_start = datetime.combine(
            local_start.date(), time(9, 30)
        ) + timedelta(minutes=bucket_number * 5)

        if self.current_bucket_start is None:
            self.current_bucket_start = bucket_start
            self.current_bucket_closes = [bar.Close]
        elif bucket_start == self.current_bucket_start:
            expected_minute = self.current_bucket_start + timedelta(
                minutes=len(self.current_bucket_closes)
            )

            if local_start != expected_minute:
                self.current_bucket_start = bucket_start
                self.current_bucket_closes = [bar.Close]
                self.last_minute_start = local_start
                return

            self.current_bucket_closes.append(bar.Close)
        elif bucket_start > self.current_bucket_start:
            if len(self.current_bucket_closes) == 5:
                completed_close = self.current_bucket_closes[-1]
                completed_end = self.current_bucket_start + timedelta(minutes=5)
                self._process_five_minute_close(completed_end, completed_close)

            self.current_bucket_start = bucket_start
            self.current_bucket_closes = [bar.Close]
        else:
            return

        self.last_minute_start = local_start

    def _process_five_minute_close(self, bar_end: datetime, close: float):
        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(close)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        end_time = bar_end.time()
        eligible_time = time(9, 45) <= end_time <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_enter_from_current_chain()

    def _try_enter_from_current_chain(self):
        if self.latest_slice is None:
            self.Debug("Skipped entry: current Slice unavailable")
            return

        chains = self.latest_slice.OptionChains
        chain = chains.get(self.option.Symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        algorithm_date = self.Time.date()
        minimum_expiration = algorithm_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days out")
            return

        selected_expiration = expirations[0]
        spy_bar = self.latest_slice.Bars.get(self.spy)

        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Skipped entry: unavailable SPY price")
            return

        minimum_strike = 1.01 * spy_bar.Close

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(f"Entry submitted: {selected.Symbol}")

    def _manage_existing_option_position(self, slice: Slice):
        if self.entry_symbol is None:
